package com.zola.videonotes.data.subtitle

import com.zola.videonotes.domain.model.TranscriptSegment
import kotlinx.coroutines.CancellationException

/**
 * 字幕轨道统一排序（P3）：手动 zh > 手动 en > 自动 zh > 自动 en > 其余（原顺序）。
 *
 * YouTube 与 B站共用同一顺序；“自动”的判定由各平台传入
 * （YouTube：NewPipe 的 isAutoGenerated；B站：lan 的 ai- 前缀 / lan_doc 的 AI 字样）。
 *
 * 语言偏好：目前无用户级设置，缺省中文优先；后续有偏好设置时把 zh / en 换成偏好语种。
 */
internal fun <T> orderSubtitleTracks(
    tracks: List<T>,
    isAuto: (T) -> Boolean,
    langTag: (T) -> String,
): List<T> {
    fun isZh(t: T): Boolean {
        val tag = langTag(t)
        return tag.startsWith("zh", ignoreCase = true) || tag.contains("中文")
    }
    fun isEn(t: T): Boolean {
        val tag = langTag(t)
        return tag.startsWith("en", ignoreCase = true) || tag.contains("英语") || tag.contains("英文")
    }
    val picked = mutableListOf<T>()
    fun pick(pred: (T) -> Boolean) {
        for (t in tracks) {
            if (picked.none { it === t } && pred(t)) picked += t
        }
    }
    pick { !isAuto(it) && isZh(it) }
    pick { !isAuto(it) && isEn(it) }
    pick { isAuto(it) && isZh(it) }
    pick { isAuto(it) && isEn(it) }
    pick { true }
    return picked
}

/** 轨道级兜底结果：命中 / 全部为空 / 全部下载失败。 */
internal sealed interface TrackAttemptOutcome {
    data class Hit<T>(val candidate: T, val segments: List<TranscriptSegment>) : TrackAttemptOutcome
    data object Empty : TrackAttemptOutcome
    data class Failed(val error: Throwable) : TrackAttemptOutcome
}

/**
 * 按候选顺序逐条尝试一条轨道：下载 / 解析抛错 → 记下并试下一条；解析为空 → 试下一条；
 * 首条非空即返回；全部抛错 → Failed（最后一次错误）；其余情况 → Empty。
 *
 * 有轨道实际下载到内容时即使全部为空也返回 Empty（上层走 ASR），
 * 而不是 Failed：此时字幕端点可达，失败的轨道多半是死链，重试意义不大。
 * 取消原样抛出（M-19），不进兜底。
 */
internal suspend fun <T> firstNonEmptyTrack(
    candidates: List<T>,
    attempt: suspend (T) -> List<TranscriptSegment>,
): TrackAttemptOutcome {
    var lastError: Throwable? = null
    var sawDownload = false
    for (candidate in candidates) {
        try {
            val segments = attempt(candidate)
            sawDownload = true
            if (segments.isNotEmpty()) return TrackAttemptOutcome.Hit(candidate, segments)
        } catch (e: CancellationException) {
            throw e
        } catch (t: Throwable) {
            lastError = t
        }
    }
    return if (lastError != null && !sawDownload) {
        TrackAttemptOutcome.Failed(lastError)
    } else {
        TrackAttemptOutcome.Empty
    }
}
